" style=\"width: 50%; height: 100%; cursor: pointer;\"></div>\n</div>\n<button class=\"home-bottom-bar-checkout\" onclick=\"window.location.href='pages/carrinho.html'\">\n<span style=\"font-size: 15px; font-weight: bold; line-height: 1.2;\">R$ <span id=\"floating-cart-total\">0,00</span></span>\n<span style=\"font-size: 11px; font-weight: 500; opacity: 0.9; line-height: 1.2;\">Ver carrinho | Frete\n          gr\u00e1tis</span>\n</button>\n</div>\n</div>\n<script src=\"js/catalogo.js?v=1795184375140\"></script>\n<script src=\"js/app.js?v=1795184375140\"></script>\n<script src=\"js/roleta-tiktok.js?v=roleta_original_2026\"></script>\n<script>\n    function normalizeStr(str) {\n      return (str || '')\n        .toLowerCase()\n        .normalize('NFD')\n        .replace(/[\\u0300-\\u036f]/g, '')\n        .trim();\n    }\n\n    function filterProducts(query, autoScroll) {\n      if (typeof autoScroll === 'undefined') autoScroll = false;\n      const q = normalizeStr(query);\n      const cards = Array.from(document.querySelectorAll('.product-card-rec'));\n      const mainSec = document.getElementById('principais-produtos-section');\n      const recSec = document.getElementById('produtos-recomendados-section');\n      const catSec = document.getElementById('categorias-section');\n      const grid = document.getElementById('recommended-grid');\n\n      // Se pesquisou algo: oculta 'Principais Produtos' e exibe s\u00f3 os resultados\n      if (q) {\n        if (mainSec) mainSec.style.display = 'none';\n        if (catSec) catSec.style.display = 'none';\n        if (recSec) recSec.style.display = 'block';\n\n        // Garante que a aba visual fique em 'Produtos'\n        const prodTab = document.querySelectorAll('.nav-tab')[1];\n        if (prodTab) {\n          document.querySelectorAll('.nav-tab').forEach(b => b.classList.remove('active'));\n          prodTab.classList.add('active');\n        }\n\n        const terms = q.split(/\\s+/).filter(Boolean);\n        const matchCards = [];\n        const noMatchCards = [];\n\n        cards.forEach(card => {\n          const nomeAttr = card.getAttribute('data-nome') || '';\n          const nomeEl = card.querySelector('.product-name');\n          const nomeText = nomeEl ? nomeEl.textContent : '';\n          const catAttr = card.getAttribute('data-cat') || '';\n          const fullText = normalizeStr(nomeAttr + ' ' + nomeText + ' ' + catAttr);\n\n          const matches = terms.every(term => fullText.includes(term));\n          if (matches) {\n            matchCards.push(card);\n          } else {\n            noMatchCards.push(card);\n          }\n        });\n\n        // Atualiza t\u00edtulo para mostrar resultados da busca\n        const titleEl = recSec ? recSec.querySelector('h2') : null;\n        if (titleEl) {\n          titleEl.innerHTML = `Resultados para \"${query.trim()}\" (${matchCards.length}) <span onclick=\"limparBusca()\" style=\"font-size:11px;font-weight:normal;color:#ff2d55;margin-left:8px;cursor:pointer;text-decoration:underline;\">Limpar</span>`;\n        }\n\n        // Remove aviso anterior de vazio\n        const existingEmpty = document.getElementById('no-products-found-msg');\n        if (existingEmpty) existingEmpty.remove();\n\n        // Reinsere no grid: primeiro os que batem, depois os ocultos\n        if (grid) {\n          matchCards.forEach(c => {\n            c.classList.remove('hidden');\n            c.style.removeProperty('display');\n            grid.appendChild(c);\n          });\n          noMatchCards.forEach(c => {\n            c.classList.add('hidden');\n            c.style.setProperty('display', 'none', 'important');\n            grid.appendChild(c);\n          });\n\n          if (matchCards.length === 0) {\n            const emptyEl = document.createElement('div');\n            emptyEl.id = 'no-products-found-msg';\n            emptyEl.style.cssText = 'grid-column: 1 / -1; width: 100%; padding: 40px 16px; text-align: center; color: #666; background: #fff; border-radius: 8px; margin: 10px 0;';\n            emptyEl.innerHTML = `\n              <div style=\"font-size: 32px; margin-bottom: 8px;\">\ud83d\udd0d</div>\n              <p style=\"font-size: 15px; font-weight: 700; color: #222; margin-bottom: 6px;\">Nenhum produto encontrado</p>\n              <p style=\"font-size: 13px; color: #888; margin-bottom: 14px;\">N\u00e3o encontramos nenhum item correspondente a \"<strong>${query.trim()}</strong>\".</p>\n              <button onclick=\"limparBusca()\" style=\"padding: 8px 18px; background: #ff2b56; color: #fff; border: none; border-radius: 20px; font-size: 13px; font-weight: 600; cursor: pointer;\">Ver todos os produtos</button>\n            `;\n            grid.appendChild(emptyEl);\n          }\n        }\n\n        if (autoScroll && recSec) {\n          recSec.scrollIntoView({ behavior: 'smooth', block: 'start' });\n        }\n      } else {\n        // Campo vazio: restaura tudo\n        limparBusca();\n      }\n    }\n\n    function limparBusca() {\n      const mainSec = document.getElementById('principais-produtos-section');\n      const recSec = document.getElementById('produtos-recomendados-section');\n      const catSec = document.getElementById('categorias-section');\n      const searchInput = document.getElementById('search-input');\n\n      // Restaura tudo\n      if (mainSec) mainSec.style.display = 'block';\n      if (recSec) recSec.style.display = 'block';\n      if (catSec) catSec.style.display = 'none';\n      if (searchInput) searchInput.value = '';\n\n      const existingEmpty = document.getElementById('no-products-found-msg');\n      if (existingEmpty) existingEmpty.remove();\n\n      // Restaura o t\u00edtulo\n      const titleEl = recSec ? recSec.querySelector('h2') : null;\n      if (titleEl) titleEl.textContent = 'Produtos Recomendados';\n\n      // Exibe todos os cards e reordena de volta \u00e0 ordem original\n      const grid = document.getElementById('recommended-grid');\n      const cards = document.querySelectorAll('.product-card-rec');\n      cards.forEach(c => {\n        c.classList.remove('hidden');\n        c.style.removeProperty('display');\n        if (grid) grid.appendChild(c);\n      });\n\n      // Garante aba 'P\u00e1gina inicial'\n      document.querySelectorAll('.nav-tab').forEach(b => b.classList.remove('active'));\n      const homeTab = document.querySelectorAll('.nav-tab')[0];\n      if (homeTab) homeTab.classList.add('active');\n    }\n\n    \n    // Switch de Abas Oficial TikTok Shop\n    \n    // Switch de Abas Oficial TikTok Shop\n    \n    \n    function switchTab(btn, tab) {\n      document.querySelectorAll('.nav-tab').forEach(b => b.classList.remove('active'));\n      if (btn) btn.classList.add('active');\n\n      const mainSec = document.getElementById('principais-produtos-section');\n      const novosSec = document.getElementById('novos-lancamentos-section');\n      const recSec = document.getElementById('produtos-recomendados-section');\n      const catSec = document.getElementById('categorias-section');\n      const subBar = document.getElementById('subfilter-produtos-bar');\n      const grid = document.getElementById('recommended-grid');\n      const divider = document.querySelector('.divider-home-rec');\n\n      // Reseta scroll para o topo absoluto\n      window.scrollTo({ top: 0, behavior: 'instant' });\n\n      if (tab === 'home') {\n        document.body.classList.remove('is-tab-produtos');\n        if (mainSec) mainSec.style.display = 'block';\n        if (novosSec) novosSec.style.display = 'block';\n        if (recSec) recSec.style.display = 'block';\n        if (catSec) catSec.style.display = 'none';\n        if (subBar) subBar.style.display = 'none';\n        if (divider) divider.style.setProperty('display', 'flex', 'important');\n        if (grid) grid.classList.remove('produtos-layout-list');\n        document.querySelectorAll('.product-card-rec').forEach(c => c.style.display = '');\n      } else if (tab === 'produtos') {\n        document.body.classList.add('is-tab-produtos');\n        if (mainSec) mainSec.style.display = 'none';\n        if (novosSec) novosSec.style.display = 'none';\n        if (recSec) recSec.style.display = 'block';\n        if (catSec) catSec.style.display = 'none';\n        if (subBar) subBar.style.display = 'flex';\n        if (divider) divider.style.setProperty('display', 'none', 'important');\n        if (grid) grid.classList.remove('produtos-layout-list');\n        document.querySelectorAll('.product-card-rec').forEach(c => c.style.display = '');\n      } else if (tab === 'categorias') {\n        document.body.classList.remove('is-tab-produtos');\n        if (mainSec) mainSec.style.display = 'none';\n        if (novosSec) novosSec.style.display = 'none';\n        if (recSec) recSec.style.display = 'none';\n        if (catSec) catSec.style.display = 'block';\n        if (subBar) subBar.style.display = 'none';\n      }\n    }\n\n\n    function filterByCategory(catName) {\n      const produtosTabBtn = document.querySelectorAll('.nav-tab')[1];\n      switchTab(produtosTabBtn, 'produtos');\n\n      const cards = document.querySelectorAll('.product-card-rec');\n      cards.forEach(card => {\n        const cat = card.getAttribute('data-cat') || '';\n        const nome = card.getAttribute('data-nome') || '';\n        if (cat.toLowerCase().includes(catName.toLowerCase()) || nome.toLowerCase().includes(catName.toLowerCase())) {\n          card.style.display = '';\n        } else {\n          card.style.display = 'none';\n        }\n      });\n    }\n\n    // Sub-filtro da aba Produtos: Recomendado | Mais vendidos | Lan\u00e7amentos\n    function setSubFilter(el, type) {\n      document.querySelectorAll('.subfilter-item').forEach(item => item.classList.remove('active'));\n      if (el) el.classList.add('active');\n\n      const grid = document.getElementById('recommended-grid');\n      if (!grid) return;\n      const cards = Array.from(grid.querySelectorAll('.product-card-rec'));\n\n      if (type === 'mais-vendidos') {\n        cards.sort((a, b) => {\n          const vA = parseInt(a.getAttribute('data-vendas') || '0', 10);\n          const vB = parseInt(b.getAttribute('data-vendas') || '0', 10);\n          return vB - vA;\n        });\n      } else if (type === 'lancamentos') {\n        cards.sort((a, b) => {\n          const idA = parseInt(a.getAttribute('data-id') || '0', 10);\n          const idB = parseInt(b.getAttribute('data-id') || '0', 10);\n          return idB - idA;\n        });\n      } else {\n        // Recomendado: produto 104 primeiro, seguido dos outros\n        cards.sort((a, b) => {\n          const hrefA = a.getAttribute('href') || '';\n          const hrefB = b.getAttribute('href') || '';\n          if (hrefA.includes('produto-52.html')) return -1;\n          if (hrefB.includes('produto-52.html')) return 1;\n          return 0;\n        });\n      }\n\n      cards.forEach(card => grid.appendChild(card));\n    }\n\n    window.applySubFilter = setSubFilter;\n    window.setSubFilter = setSubFilter;\n    window.switchTab = switchTab;\n    window.filterByCategory = filterByCategory;\n\n    function toggleLayoutView() {\n      const grid = document.getElementById('recommended-grid');\n      if (!grid) return;\n      grid.classList.toggle('produtos-layout-list');\n    }\n    \n    document.addEventListener('DOMContentLoaded', () => {\n      if (typeof initShareTooltip === 'function') {\n        initShareTooltip();\n      }\n    });\n</script>\n</body>\n</html>";
